import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(HERE, "fixtures") + os.sep
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)
import sys, re
from shots import run, BASE, OUT

results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def as_role(page, role):
    page.get_by_role("button", name="Account menu").click()
    page.get_by_role("menuitem", name=role).click()
    page.wait_for_timeout(350)
def toast(page):
    return page.locator("[aria-live=polite]").last.inner_text()

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main")

    # 1. Person box: email fits
    page.goto(BASE + "/people?person=p-sm4"); page.wait_for_selector("dialog[open]")
    dlg = page.locator("dialog[open]")
    over = page.evaluate("""() => { const d = document.querySelector('dialog[open]'); const a = d.querySelector('a[href^="mailto:"]'); const dl = a.closest('dl'); const r = a.getBoundingClientRect(), b = dl.getBoundingClientRect(); return [Math.round(r.right), Math.round(b.right), d.scrollWidth > d.clientWidth]; }""")
    check("Person box: the email stays inside its column and does not run under the tickets", over[0] <= over[1] + 1 and not over[2], over)
    check("Person box: phone and email are links to ring or write", dlg.locator('a[href="tel:0852417611"]').count() + dlg.locator('a[href^="tel:"]').count() >= 1 and dlg.locator('a[href="mailto:darragh.lenihan@abcconstruction.example"]').count() == 1)
    check("Person box: shows the access level with a link to change it", "Access level" in dlg.inner_text() and "Site manager" in dlg.inner_text() and dlg.get_by_role("link", name="Change").count() == 1)
    page.screenshot(path=f"{OUT}/80-person-box.png")
    page.set_viewport_size({"width": 390, "height": 844}); page.wait_for_timeout(200)
    over = page.evaluate("""() => { const d = document.querySelector('dialog[open]'); const a = d.querySelector('a[href^="mailto:"]'); const r = a.getBoundingClientRect(); return [Math.round(r.right), window.innerWidth]; }""")
    check("Person box: email also fits at phone width", over[0] <= over[1], over)
    page.screenshot(path=f"{OUT}/81-person-box-mobile.png")
    page.set_viewport_size({"width": 1440, "height": 900})

    # 2. Photos: camera or file, real picture, open and download
    page.goto(BASE + "/projects/C720?tab=photos"); page.wait_for_timeout(400)
    if page.get_by_role("button", name="Add a photo").count() == 0:
        page.get_by_role("tab", name="Photos").click(); page.wait_for_timeout(300)
    n0 = page.locator("main ul li").count()
    page.get_by_role("button", name="Add a photo").click()
    dlg = page.locator("dialog[open]")
    check("Photos: both a camera button and a file button are offered", dlg.get_by_role("button", name="Take a photo", exact=True).count() == 1 and dlg.get_by_role("button", name="Choose a file", exact=True).count() == 1)
    cam = dlg.get_by_label("Take a photo with the camera")
    check("Photos: the camera input asks the device for its rear camera", cam.get_attribute("capture") == "environment" and cam.get_attribute("accept") == "image/*")
    check("Photos: cannot be added without a picture", dlg.get_by_role("button", name="Add photo").is_disabled())
    dlg.get_by_label("Choose a photo from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(500)
    check("Photos: a file that is not a picture is refused in plain words", "not a picture" in dlg.inner_text(), dlg.inner_text()[-200:])
    dlg.get_by_label("Choose a photo from this device").set_input_files(FIX + "site-photo.jpg"); page.wait_for_timeout(700)
    check("Photos: the chosen picture is previewed", dlg.locator("img").count() == 1 and "site-photo.jpg" in dlg.inner_text())
    dlg.get_by_label("Caption").fill("North elevation, repointing under way")
    dlg.get_by_label("Stage").select_option("During")
    page.screenshot(path=f"{OUT}/82-add-photo.png")
    dlg.get_by_role("button", name="Add photo").click(); page.wait_for_timeout(400)
    f = data(page, "(() => { const f = db.files.find(f => f.caption==='North elevation, repointing under way'); return [f.dataUrl.slice(0,23), f.sizeKb, f.addedBy, f.stage] })()")
    check("Photos: the real picture is saved, shrunk to a sensible size", f[0] == "data:image/jpeg;base64," and 5 < f[1] < 600 and f[2] == "Aidan King" and f[3] == "During", f)
    check("Photos: it appears first in the grid as a real image", page.locator("main ul li").count() == n0 + 1 and page.locator("main ul li").first.locator("img").count() == 1)
    page.locator("main ul li").first.locator("button").click(); page.wait_for_timeout(300)
    dlg = page.locator("dialog[open]")
    dims = dlg.locator("img").evaluate("i => [i.naturalWidth, i.naturalHeight]")
    link = dlg.get_by_role("link", name="Download")
    check("Photos: opens large, at most 1280 pixels on its long side", dims == [1280, 960], dims)
    with page.expect_download() as dl:
        link.click()
    check("Photos: downloads as a file named after the caption", dl.value.suggested_filename == "North elevation, repointing under way.jpg", dl.value.suggested_filename)
    page.screenshot(path=f"{OUT}/83-photo-open.png")
    page.reload(); page.wait_for_timeout(500)
    check("Photos: the picture survives a refresh", data(page, "db.files.filter(f => f.dataUrl).length") == 1 and page.locator("main ul li img").count() == 1)

    # 4. Tickets: proof
    # In Compliance since 18 Nov: the tickets that need attention, then everything.
    page.goto(BASE + "/compliance?area=personnel"); page.wait_for_selector("table")
    n_att = page.locator("tbody tr").count()
    row = page.locator("tbody tr", has_text="Thiago Barbosa")
    row.get_by_role("button", name="Renew").click()
    page.locator("dialog[open]").get_by_role("button", name="Save renewal").click(); page.wait_for_timeout(300)
    check("Tickets: a renewal saved with no proof stays on the list as Proof needed", page.locator("tbody tr").count() == n_att and "Proof needed" in row.inner_text() and "In date" in row.inner_text(), row.inner_text())
    proof_tile = page.locator("dl[aria-label='Compliance figures'] button", has_text="Proof needed").inner_text()
    check("Tickets: the figures count what is waiting on proof", "3" in proof_tile, proof_tile)
    page.goto(BASE + "/compliance/personnel?view=list&person=p-108"); page.wait_for_selector("table")
    row = page.locator("tbody tr", has_text="Manual handling")
    row.get_by_role("button", name="Add proof").click()
    dlg = page.locator("dialog[open]")
    check("Tickets: proof cannot be attached without a file", dlg.get_by_role("button", name="Attach proof").is_disabled())
    dlg.get_by_label("Choose a proof from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(400)
    check("Tickets: only a photo or a PDF is accepted as proof", "photo of the card or a PDF" in dlg.inner_text())
    dlg.get_by_label("Choose a proof from this device").set_input_files(FIX + "cert.pdf"); page.wait_for_timeout(400)
    dlg.get_by_role("button", name="Attach proof").click(); page.wait_for_timeout(300)
    page.goto(BASE + "/compliance?area=personnel"); page.wait_for_selector("table")
    check("Tickets: once proof is attached the ticket leaves the list", page.locator("tbody tr", has_text="Thiago Barbosa").count() == 0 and page.locator("tbody tr").count() == n_att - 1)
    page.get_by_role("tab", name=re.compile("^Everything")).click(); page.wait_for_timeout(300)
    row = page.locator("tbody tr", has_text="Thiago Barbosa").filter(has_text="Manual handling")
    row.get_by_role("button", name="View proof").click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]")
    check("Tickets: the proof opens with who attached it and a download", "cert.pdf" in dlg.inner_text() and "Attached by Aidan King" in dlg.inner_text() and dlg.get_by_role("link", name="Download").get_attribute("download") == "cert.pdf")
    page.screenshot(path=f"{OUT}/84-proof.png")
    dlg.get_by_role("button", name="Close").click()
    check("Tickets: tickets from before the system say On paper file and offer Add proof", page.locator("tbody tr", has_text="On paper file").count() > 100 and page.locator("tbody tr", has_text="On paper file").filter(has_text="In date").first.get_by_role("button", name="Add proof").count() == 1, page.locator("tbody tr", has_text="On paper file").count())
    page.goto(BASE + "/people?person=p-110"); page.wait_for_timeout(300)

    # 6 and 7. Week ahead
    page.goto(BASE + "/schedule"); page.wait_for_selector("table")
    side = page.get_by_role("complementary", name="Not placed this week")
    free_all = ["Adrian Stoica", "Rafael Mendonça", "Piotr Zieliński", "Krzysztof Nowicki", "Darius Kazlauskas"]
    kn = [t for t in side.locator("li").all_inner_texts() if t.startswith("Krzysztof")]
    check("Not placed: someone with only a half day planned on Tuesday shows Tuesday as still open", kn and "Tue to Fri" in kn[0], kn)
    listed = [t.split("\n")[0] for t in side.locator("li").all_inner_texts()]
    check("Week ahead: the Not placed list shows exactly the operatives with a free day", sorted(listed) == sorted(free_all) and len(listed) > 0, (listed, free_all))
    check("Week ahead: the list says how many and who is free all week", f"Not placed {len(listed)}" in side.inner_text().replace("\n", " ") and "All week" in side.inner_text(), side.inner_text()[:160])
    page.screenshot(path=f"{OUT}/85-week-ahead-not-placed.png")
    block = page.locator("section", has=page.get_by_role("link", name="C719 St Finian's Church"))
    trades = block.get_by_label("Trade to add to C719").locator("option").all_inner_texts()
    check("Week ahead: add starts with the trade, with free counts", trades[0].startswith("Add to C719") and any("Bricklayer (" in t and "free of" in t for t in trades), trades)
    check("Week ahead: the person list waits for a trade", block.get_by_label("Person to add to C719").is_disabled())
    block.get_by_label("Trade to add to C719").select_option("Bricklayer"); page.wait_for_timeout(150)
    people = block.get_by_label("Person to add to C719").locator("option").all_inner_texts()
    check("Week ahead: only that trade is listed, each with where they are", len(people) >= 2 and all(": " in t for t in people[1:]) and any(t.startswith("Florin Dobre: on C723") for t in people), people)
    florin = data(page, "db.people.find(p=>p.name==='Florin Dobre').id")
    block.get_by_label("Person to add to C719").select_option(florin); page.wait_for_timeout(150)
    check("Week ahead: choosing Florin, who is on C723 all week, warns before anything is planned", "On C723 all week" in block.inner_text() and "double books" in block.inner_text() and block.get_by_role("button", name="Plan anyway").count() == 1)
    page.screenshot(path=f"{OUT}/86-add-by-trade.png")
    block.get_by_role("button", name="Plan anyway").click(); page.wait_for_timeout(300)
    check("Week ahead: planning anyway shows the clashes", "double booking" in main.inner_text() and block.locator("tr", has_text="Florin Dobre").count() == 1)
    block.get_by_role("button", name="Florin Dobre: contact details and options").click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]")
    check("Week ahead: clicking a name opens a box with phone and email to ring or write", dlg.locator("a[href^='tel:']").count() == 1 and dlg.locator("a[href='mailto:florin.dobre@abcconstruction.example']").count() == 1, dlg.inner_text()[:200])
    check("Week ahead: the box shows his week with both sites on each day", dlg.locator("li", has_text=" + ").count() == 5 and "Florin Dobre is on C723 and C719 all week (5 days)" in main.inner_text(), dlg.inner_text())
    page.screenshot(path=f"{OUT}/87-person-week-box.png")
    dlg.get_by_role("button", name="Take off C719").click(); page.wait_for_timeout(300)
    st = data(page, f"[db.plan.filter(p=>p.personId==='{florin}'&&p.projectId==='pr-C719').length, db.assignments.filter(a=>a.personId==='{florin}'&&a.projectId==='pr-C719').length, db.plan.filter(p=>p.personId==='{florin}'&&p.projectId==='pr-C723'&&p.date>day).length]")
    check("Week ahead: Take off removes his whole row from C719 and leaves C723 alone", block.locator("tr", has_text="Florin Dobre").count() == 0 and st[0] == 0 and st[1] == 0 and st[2] >= 5, st)
    check("Week ahead: and the clashes he caused are gone", "Florin Dobre is on" not in main.inner_text())
    # someone free: place them day by day from the Not placed list
    free_name = "Adrian Stoica"
    pid = data(page, f"db.people.find(p=>p.name==={free_name!r}).id")
    days = data(page, "(() => { const out=[]; let d=new Date(day+'T12:00:00Z'); do { d.setUTCDate(d.getUTCDate()+1) } while (d.getUTCDay()!==1); for (let i=0;i<5;i++){ out.push(d.toISOString().slice(0,10)); d.setUTCDate(d.getUTCDate()+1) } return out })()")
    plan = lambda: data(page, f"db.plan.filter(p=>p.personId==='{pid}'&&p.date>='{days[0]}'&&p.date<='{days[4]}').map(p=>[p.projectId,p.date,p.part||'full',p.overtimeHours||0]).sort()")
    side.get_by_role("button", name=free_name).click(); page.wait_for_timeout(250)
    box = page.locator("dialog[open]").first
    check("Person box: no site dropdown or Plan free days button any more", box.get_by_role("button", name="Plan free days").count() == 0 and box.locator("select").count() == 0)
    check("Person box: a free person has five Free days, each one a button", box.locator("li button", has_text=re.compile("Free")).count() == 5)
    def open_day(i):
        box.locator("li button").nth(i).click(); page.wait_for_timeout(250)
        return page.locator("dialog[open]").last
    dlg = open_day(2)
    check("Day planner: asks which site and offers full day, half day and overtime", dlg.get_by_label("Site").count() == 1 and [t.inner_text() for t in dlg.get_by_role("tab").all()] == ["Full day", "Half day", "Full day + overtime"] and dlg.get_by_role("button", name="Put on site").is_disabled(), dlg.inner_text())
    dlg.get_by_label("Site").select_option("pr-C719"); dlg.get_by_role("tab", name="Half day").click()
    page.screenshot(path=f"{OUT}/90-plan-day.png")
    dlg.get_by_role("button", name="Put on C719").click(); page.wait_for_timeout(300)
    check("Day planner: a half day on Wednesday only is saved, nothing else", plan() == [["pr-C719", days[2], "half", 0]], plan())
    check("Person box: stays open and shows the half day with half the day still free", "C719 half" in box.inner_text() and "half free" in box.inner_text() and box.locator("li button", has_text=re.compile("Free")).count() == 4, box.inner_text())
    check("Week ahead: the site grid shows it as a half day", block.locator("tr", has_text=free_name).locator("button", has_text="Half day").count() == 1)
    dlg = open_day(2)
    check("Day planner: reopening the day starts on the site already planned, with Take off", dlg.get_by_label("Site").input_value() == "pr-C719" and dlg.get_by_role("tab", name="Half day").get_attribute("aria-selected") == "true" and dlg.get_by_role("button", name="Take off this day").count() == 1)
    dlg.get_by_label("Site").select_option("pr-C723"); dlg.get_by_role("tab", name="Half day").click(); page.wait_for_timeout(150)
    check("Day planner: a second half day elsewhere is explained as a split day, not a clash", "one full day split across two sites" in dlg.inner_text() and "double books" not in dlg.inner_text(), dlg.inner_text())
    dlg.get_by_role("button", name="Put on C723").click(); page.wait_for_timeout(300)
    check("Week ahead: two half days on two sites raise no double booking", f"{free_name} is on" not in main.inner_text() and len(plan()) == 2, plan())
    dlg = open_day(3)
    dlg.get_by_label("Site").select_option("pr-C719"); dlg.get_by_role("tab", name="Full day + overtime").click()
    ot = dlg.get_by_label("Overtime hours"); ot.click(); ot.press("ControlOrMeta+a"); page.keyboard.type("2.5", delay=40)
    dlg.get_by_role("button", name="Put on C719").click(); page.wait_for_timeout(300)
    check("Day planner: a full day with 2.5 hours overtime is saved and shown", ["pr-C719", days[3], "full", 2.5] in plan() and block.locator("tr", has_text=free_name).locator("button", has_text="On site +2.5h").count() == 1, plan())
    dlg = open_day(2)
    dlg.get_by_label("Site").select_option("pr-C723"); dlg.get_by_role("tab", name="Full day", exact=True).click(); page.wait_for_timeout(150)
    check("Day planner: making one half a full day warns that it double books", "double books" in dlg.inner_text())
    dlg.get_by_role("button", name="Save change").click(); page.wait_for_timeout(300)
    check("Week ahead: a full day plus a half day is flagged as a double booking", f"{free_name} is on" in main.inner_text() and page.get_by_role("button", name="Send week to operatives").is_disabled())
    dlg = open_day(2)
    dlg.get_by_label("Site").select_option("pr-C723"); page.wait_for_timeout(100)
    dlg.get_by_role("button", name="Take off this day").click(); page.wait_for_timeout(300)
    check("Day planner: Take off this day clears just that site and day", f"{free_name} is on" not in main.inner_text() and len(plan()) == 2, plan())
    box.get_by_role("button", name="Close").click(); page.wait_for_timeout(200)
    check("Not placed: he is still listed, with Monday, Tuesday and Friday free and Wednesday half", any(t.startswith(free_name) for t in side.locator("li").all_inner_texts()), side.inner_text())
    # Kevin Shortall cannot work next week (his scaffolding ticket runs out first), so another of C719's crew.
    cell = block.locator("tr", has_text="Marek Wiśniewski").locator("button[aria-pressed=true]").first
    cell.click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]").last
    dlg.get_by_role("tab", name="Half day").click(); dlg.get_by_role("button", name="Save change").click(); page.wait_for_timeout(300)
    check("Week ahead: a day in the grid can be changed to a half day in place", block.locator("tr", has_text="Marek Wiśniewski").locator("button", has_text="Half day").count() == 1)
    check("Sample data: one half day is already planned next week (Krzysztof Nowicki, Tuesday)", data(page, "db.plan.filter(p => p.personId==='p-126' && p.part==='half').length") == 1)
    side.get_by_label("Show one trade").select_option(index=1); page.wait_for_timeout(150)
    shown = side.locator("li").all_inner_texts()
    check("Week ahead: the list can be narrowed to one trade", len(shown) >= 1 and len({t.split("\n")[1] for t in shown}) == 1, shown)
    page.set_viewport_size({"width": 1100, "height": 900}); page.wait_for_timeout(250)
    y_side = side.bounding_box()["y"]; y_first = page.locator("section table").first.bounding_box()["y"]
    check("Week ahead: on a narrower screen the list sits above the sites", y_side < y_first, (y_side, y_first))
    page.set_viewport_size({"width": 1440, "height": 900})

    # 5. Access: by role and by person
    # 16 Nov: Roles and access moved from Settings to Admin.
    page.locator("nav[aria-label=Departments]").get_by_role("link", name="Admin").click(); page.wait_for_selector("text=Requests")
    page.get_by_role("link", name="Roles and access").click(); page.wait_for_selector("text=What they can do")
    check("Access: by role lists seventeen permissions for three levels (two for Compliance, 18 Nov)", page.locator("section", has_text="What they can do").locator("tbody tr").count() == 17 and page.get_by_role("switch", name="Site manager: Plan the week ahead").get_attribute("aria-checked") == "false")
    page.screenshot(path=f"{OUT}/88-access-by-role.png", full_page=True)
    page.get_by_role("tab", name="By person").click(); page.wait_for_timeout(300)
    lst = page.get_by_role("list", name="Office and management staff")
    check("Access: by person lists the twelve office staff, not the managing director or operatives", lst.locator("li").count() == 12 and "Aidan King" not in lst.inner_text() and "Fergal Noone" not in lst.inner_text(), lst.locator("li").count())
    check("Access: people who already differ from their level are flagged", "2 exceptions" in lst.locator("li", has_text="Declan Furey").inner_text() and "3 exceptions" in lst.locator("li", has_text="Pat Scully").inner_text())
    lst.get_by_role("button", name="Darragh Lenihan").click(); page.wait_for_timeout(250)
    check("Access: Darragh starts exactly at site manager level", "Exactly the site manager level" in main.inner_text() and page.get_by_role("switch", name="Darragh Lenihan: Plan the week ahead").get_attribute("aria-checked") == "false")
    page.get_by_role("switch", name="Darragh Lenihan: Plan the week ahead").click()
    page.get_by_role("switch", name="Darragh Lenihan: Costs and margins").click()
    page.get_by_role("switch", name="Darragh Lenihan: Plant and fleet").click() if page.get_by_role("switch", name="Darragh Lenihan: Plant and fleet").count() else page.get_by_role("switch", name="Darragh Lenihan: Plant").click()
    page.wait_for_timeout(250)
    pa = data(page, "db.personAccess.find(a => a.id==='p-sm4')")
    check("Access: three exceptions are stored for Darragh only", pa["perms"] == {"planWeek": True, "seeMargins": True} and pa["departments"] == {"plant": False} and "3 exceptions to the site manager level" in main.inner_text(), pa)
    check("Access: the level itself is untouched", data(page, "db.access.find(a=>a.id==='site').perms.includes('planWeek')") is False)
    page.screenshot(path=f"{OUT}/89-access-by-person.png", full_page=True)
    page.get_by_role("switch", name="Darragh Lenihan: Costs and margins").click(); page.wait_for_timeout(200)
    check("Access: switching one back removes the exception rather than storing it", data(page, "Object.keys(db.personAccess.find(a => a.id==='p-sm4').perms)") == ["planWeek"])
    page.get_by_role("button", name="Sign in as Darragh to check").click(); page.wait_for_timeout(500)
    check("Access: signing in as Darragh lands on his home with his name in the top bar", "/people/timesheet" in page.url and "Darragh Lenihan" in page.locator("header").first.inner_text(), page.url)
    bar = page.locator("nav[aria-label=Departments]")
    check("Access: his department bar has lost Plant", bar.get_by_role("link", name="Plant").count() == 0 and bar.get_by_role("link", name="Schedule").count() == 1)
    opts = page.get_by_label("Site", exact=True).locator("option").all_inner_texts()
    mine = data(page, "db.projects.filter(p => p.siteManagerId==='p-sm4' && p.status==='Live').map(p => p.code)")
    check("Access: he sees only the sites he runs", len(opts) == len(mine) and all(any(o.startswith(c) for c in mine) for o in opts), (opts, mine))
    page.goto(BASE + "/schedule"); page.wait_for_selector("table")
    check("Access: Darragh can now plan the week", page.get_by_role("button", name="Send week to operatives").count() == 1 and page.locator("button[aria-pressed]:not([disabled])").count() > 0)
    page.locator("button[aria-pressed=false]:not([disabled])").first.click(); page.wait_for_timeout(250)
    page.locator("dialog[open]").last.get_by_role("button", name="Put on C").click(); page.wait_for_timeout(250)
    check("Access: Darragh's change is saved", page.locator("[aria-live=polite]").last.inner_text() != "")
    as_role(page, "Site manager")
    check("Access: the ordinary site manager (Eoin Brosnan) still cannot plan", "Eoin Brosnan" in page.locator("header").first.inner_text())
    page.goto(BASE + "/schedule"); page.wait_for_selector("table")
    check("Access: Eoin's week is read only, with the contact box still available", page.get_by_role("button", name="Send week to operatives").count() == 0 and page.locator("button[aria-pressed]:not([disabled])").count() == 0 and page.locator("button[aria-label$='contact details and options']").count() > 0)
    page.locator("button[aria-label$='contact details and options']").first.click(); page.wait_for_timeout(200)
    check("Access: without the permission the box has contact details but no Take off button", page.locator("dialog[open] a[href^='tel:']").count() == 1 and page.locator("dialog[open]").get_by_role("button", name="Take off").count() == 0)
    page.locator("dialog[open]").get_by_role("button", name="Close").click()
    page.goto(BASE + "/people/holidays"); page.wait_for_selector("table")
    check("Access: a site manager cannot approve leave or record it", page.get_by_role("button", name="Approve").count() == 0 and page.get_by_role("button", name="Record leave").count() == 0)
    page.goto(BASE + "/people/certs"); page.wait_for_selector("table")
    check("Access: or record tickets", page.get_by_role("button", name="Renew").count() == 0 and page.get_by_role("button", name="Add proof").count() == 0 and page.get_by_role("button", name="Record a new ticket").count() == 0)
    page.goto(BASE + "/people"); page.wait_for_selector("table")
    check("Access: or add employees", page.get_by_role("button", name="Add employee").count() == 0)

    # by role: give every site manager approve leave; accounts lose mark, cannot price
    as_role(page, "Managing director")
    page.goto(BASE + "/settings/roles"); page.wait_for_selector("text=What they can do")
    page.get_by_role("switch", name="Site manager: Approve leave").click(); page.wait_for_timeout(200)
    as_role(page, "Site manager")
    page.goto(BASE + "/people/holidays"); page.wait_for_selector("table")
    check("Access: switching Approve leave on for the level gives every site manager the buttons", page.get_by_role("button", name="Approve").count() > 0)
    as_role(page, "Accounts")
    page.goto(BASE + "/sales"); page.wait_for_timeout(400)
    check("Access: accounts can read the pipeline but not log enquiries", page.get_by_role("button", name="Log enquiry").count() == 0 and page.locator("section[aria-label='Sent']").count() == 1)
    page.locator("section[aria-label='Drafting'] a").first.click(); page.wait_for_timeout(400)
    check("Access: and a draft quote is read only for them", page.locator("input[aria-label='Item description']").count() == 0 and page.get_by_role("button", name="Send to client").count() + page.get_by_role("button", name="Approve and send").count() == 0)
    page.goto(BASE + "/people/timesheet"); page.wait_for_selector("table")
    # On a Monday there are no earlier days in the week yet, so look at last week.
    if page.locator("button[title='Correct this day']").count() == 0: page.get_by_role("button", name="Earlier week").click(); page.wait_for_timeout(250)
    check("Access: accounts can correct earlier days but not mark today", page.locator("select[aria-label^='Today for']").count() == 0 and page.locator("button[title='Correct this day']").count() > 0 and page.get_by_role("button", name="Send today's time stamps").count() == 0)
    as_role(page, "Site manager")
    page.goto(BASE + "/dashboard/approvals"); page.wait_for_timeout(400)
    check("Access: a site manager still cannot open Approvals at all", "/dashboard" not in page.url, page.url)
    as_role(page, "Managing director")
    page.goto(BASE + "/people?person=p-hs"); page.wait_for_selector("dialog[open]")
    page.locator("dialog[open]").get_by_role("link", name="Change").click(); page.wait_for_timeout(400)
    check("Access: Change on a person's box opens their access page", "person=p-hs" in page.url and "Declan Furey" in main.locator("h2").first.inner_text(), page.url)
    page.get_by_role("button", name="Clear exceptions").click(); page.wait_for_timeout(200)
    check("Access: Clear exceptions puts a person back to their level", data(page, "db.personAccess.some(a => a.id==='p-hs')") is False and "Exactly the site manager level" in main.inner_text())
    main.get_by_label("Access level").select_option("accounts"); page.wait_for_timeout(250)
    check("Access: a person can be moved to another level", data(page, "db.people.find(p=>p.id==='p-hs').level") == "accounts" and "Exactly the accounts level" in main.inner_text())
    # reset keeps working and clears everything
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click(); page.wait_for_timeout(200)
    page.locator("dialog[open]").get_by_role("button", name="Reset").click(); page.wait_for_timeout(500)
    check("Reset: photos, proof and access changes all go back to the starting point", data(page, "[db.files.filter(f=>f.dataUrl).length, db.personAccess.length, db.access.find(a=>a.id==='site').perms.includes('approveLeave'), db.people.flatMap(p=>p.certs).filter(c=>c.proof||c.proofNeeded).length]") == [0, 2, False, 0])

errs = []
try:
    errs = run(steps)
except Exception as ex:
    print("STOPPED EARLY:", str(ex).split("\n")[0][:400]); import traceback; traceback.print_exc()
for name, ok, detail in results:
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else f"  [{detail[:300]}]"))
print("console problems:", errs)
print(f"{sum(1 for r in results if r[1])}/{len(results)} passed")
